import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { addNotice, addStudy, uploadPDF } from "../../services/api";

const AdminDashboard = () => {
  const navigate = useNavigate();

  const [file, setFile] = useState(null);

  const [noticeTitle, setNoticeTitle] = useState("");
  const [noticeContent, setNoticeContent] = useState("");

  const [studyTitle, setStudyTitle] = useState("");
  const [studySubject, setStudySubject] = useState("");
  const [studyContent, setStudyContent] = useState("");

  const handleAddNotice = async () => {
    const res = await addNotice({
      title: noticeTitle,
      content: noticeContent
    });
    alert(res.data.message);
  };

  const handleAddStudy = async () => {
    const res = await addStudy({
      title: studyTitle,
      subject: studySubject,
      content: studyContent
    });
    alert(res.data.message);
  };

  const handleUpload = async () => {
    const res = await uploadPDF(file);
    alert("PDF Uploaded");
  };

  return (
    <div style={styles.container}>

      <h1>Admin / Teacher Dashboard</h1>

      {/* 🔥 NAVIGATION */}
      <button onClick={() => navigate("/chatbot")}>
        Go to Chatbot 🤖
      </button>

      {/* 📢 NOTICE */}
      <div style={styles.card}>
        <h2>Add Notice</h2>

        <input placeholder="Title" onChange={(e) => setNoticeTitle(e.target.value)} />
        <input placeholder="Content" onChange={(e) => setNoticeContent(e.target.value)} />

        <button onClick={handleAddNotice}>Add Notice</button>
      </div>

      {/* 📚 STUDY */}
      <div style={styles.card}>
        <h2>Add Study</h2>

        <input placeholder="Title" onChange={(e) => setStudyTitle(e.target.value)} />
        <input placeholder="Subject" onChange={(e) => setStudySubject(e.target.value)} />
        <input placeholder="Content" onChange={(e) => setStudyContent(e.target.value)} />

        <button onClick={handleAddStudy}>Add Study</button>
      </div>

      {/* 📁 UPLOAD */}
      <div style={styles.card}>
        <h2>Upload PDF</h2>

        <input type="file" onChange={(e) => setFile(e.target.files[0])} />
        <button onClick={handleUpload}>Upload</button>
      </div>

    </div>
  );
};

export default AdminDashboard;

const styles = {
  container: { padding: 20, background: "#0f172a", color: "white" },
  card: { margin: 20, padding: 20, background: "#1e293b" }
};
